from pathlib import Path

path = Path('ClockTimer.js')
text = path.read_text()

old = '''        #isValidFormat(\n            value\n        ) {\n            if (\n                typeof value !==\n                    "string"\n            ) {\n                return false;\n            }\n\n            const military =\n                this.getAttribute(\n                    "military-time"\n                ) !== "false";\n\n            if (military) {\n                return /^(?:hhmm|hhmmss)$/.test(\n                    value\n                );\n            }\n\n            return /^h:mm(?::ss)?(?: ?(?:a\\/p|A\\/P|AM\\/PM|A\\.M\\.\\/P\\.M\\.|am\\/pm|a\\.m\\.\\/p\\.m\\.))?$/.test(\n                value\n            );\n        }\n'''
new = '''        #isValidFormat(\n            value\n        ) {\n            if (\n                typeof value !==\n                    "string"\n            ) {\n                return false;\n            }\n\n            const military =\n                this.getAttribute(\n                    "military-time"\n                ) !== "false";\n\n            if (military) {\n                return /^(?:hhmm|hhmmss)$/.test(\n                    value\n                );\n            }\n\n            return /^(?:hh:mm(?::ss)?|(?:h|0h):mm(?::ss)?(?: ?(?:a\\/p|A\\/P|AM\\/PM|A\\.M\\.\\/P\\.M\\.|am\\/pm|a\\.m\\.\\/p\\.m\\.))?)$/.test(\n                value\n            );\n        }\n'''
if old not in text:
    raise SystemExit('isValidFormat block not found')
text = text.replace(old, new, 1)

start = text.index('        #updateDisplay(\n')
end = text.index('        #renderHours() {\n', start)
old_block = text[start:end]
new_block = '''        #updateDisplay(\n            now\n        ) {\n            const military =\n                this.getAttribute(\n                    "military-time"\n                ) !== "false";\n\n            const format =\n                this.getAttribute(\n                    "format"\n                ) ??\n                this.#getDefaultFormat();\n\n            const rawHours =\n                now.getHours();\n\n            const minutes =\n                String(\n                    now.getMinutes()\n                ).padStart(\n                    2,\n                    "0"\n                );\n\n            const seconds =\n                String(\n                    now.getSeconds()\n                ).padStart(\n                    2,\n                    "0"\n                );\n\n            if (military) {\n                const hourText =\n                    String(\n                        rawHours\n                    ).padStart(\n                        2,\n                        "0"\n                    );\n\n                this.#timeElement.textContent =\n                    format === "hhmmss"\n                        ? `${hourText}${minutes}${seconds}`\n                        : `${hourText}${minutes}`;\n\n                return;\n            }\n\n            const militaryHour =\n                format.startsWith(\n                    "hh:"\n                );\n\n            const padHour =\n                militaryHour ||\n                format.startsWith(\n                    "0h:"\n                );\n\n            const hourValue =\n                militaryHour\n                    ? rawHours\n                    : rawHours % 12 || 12;\n\n            const hourText =\n                padHour\n                    ? String(hourValue).padStart(2, "0")\n                    : String(hourValue);\n\n            const hasSeconds =\n                /:ss(?: |$)/.test(\n                    format\n                );\n\n            let result =\n                `${hourText}:${minutes}`;\n\n            if (hasSeconds) {\n                result +=\n                    `:${seconds}`;\n            }\n\n            if (!militaryHour) {\n                const suffixMatch =\n                    format.match(\n                        /^(?:h|0h):mm(?::ss)?( ?)(a\\/p|A\\/P|AM\\/PM|A\\.M\\.\\/P\\.M\\.|am\\/pm|a\\.m\\.\\/p\\.m\\.)$/\n                    );\n\n                if (suffixMatch) {\n                    const space =\n                        suffixMatch[1];\n\n                    const style =\n                        suffixMatch[2];\n\n                    const pm =\n                        rawHours >= 12;\n\n                    const suffixes = {\n                        "a/p": pm ? "p" : "a",\n                        "A/P": pm ? "P" : "A",\n                        "AM/PM": pm ? "PM" : "AM",\n                        "A.M./P.M.": pm ? "P.M." : "A.M.",\n                        "am/pm": pm ? "pm" : "am",\n                        "a.m./p.m.": pm ? "p.m." : "a.m."\n                    };\n\n                    result +=\n                        space +\n                        suffixes[style];\n                }\n            }\n\n            this.#timeElement.textContent =\n                result;\n        }\n\n'''
text = text[:start] + new_block + text[end:]

old_keyframes = '''            const keyframes = [\n                {\n                    transform:\n                        "translate(-50%, -100%) rotate(0deg)"\n                },\n                {\n                    transform:\n                        "translate(-50%, -100%) rotate(360deg)"\n                }\n            ];\n\n            this.#hourHandAnimation =\n                this.#hourHand.animate(\n                    keyframes,\n'''
new_keyframes = '''            const createKeyframes =\n                hand => [\n                    {\n                        transform:\n                            this.#getHandTransform(\n                                hand,\n                                0\n                            )\n                    },\n                    {\n                        transform:\n                            this.#getHandTransform(\n                                hand,\n                                360\n                            )\n                    }\n                ];\n\n            this.#hourHandAnimation =\n                this.#hourHand.animate(\n                    createKeyframes(\n                        this.#hourHand\n                    ),\n'''
if old_keyframes not in text:
    raise SystemExit('hand keyframe block not found')
text = text.replace(old_keyframes, new_keyframes, 1)
text = text.replace('''            this.#minuteHandAnimation =\n                this.#minuteHand.animate(\n                    keyframes,\n''','''            this.#minuteHandAnimation =\n                this.#minuteHand.animate(\n                    createKeyframes(\n                        this.#minuteHand\n                    ),\n''',1)
text = text.replace('''            this.#secondHandAnimation =\n                this.#secondHand.animate(\n                    keyframes,\n''','''            this.#secondHandAnimation =\n                this.#secondHand.animate(\n                    createKeyframes(\n                        this.#secondHand\n                    ),\n''',1)

marker = '''        #synchronizeHands() {\n'''
helper = '''        #getHandTransform(\n            hand,\n            angle\n        ) {\n            const handRect =\n                hand.getBoundingClientRect();\n\n            const layerRect =\n                this.#handLayer.getBoundingClientRect();\n\n            const view =\n                this.ownerDocument\n                    ?.defaultView;\n\n            const devicePixelRatio =\n                Number.isFinite(\n                    view?.devicePixelRatio\n                ) &&\n                view.devicePixelRatio > 0\n                    ? view.devicePixelRatio\n                    : 1;\n\n            const center =\n                layerRect.left +\n                layerRect.width / 2;\n\n            const physicalWidth =\n                Math.max(\n                    1,\n                    Math.round(\n                        handRect.width *\n                        devicePixelRatio\n                    )\n                );\n\n            const phase =\n                physicalWidth % 2 === 0\n                    ? 0\n                    : 0.5;\n\n            const physicalCenter =\n                center *\n                devicePixelRatio;\n\n            const snappedCenter =\n                Math.round(\n                    physicalCenter -\n                    phase\n                ) +\n                phase;\n\n            const centerAdjustment =\n                (\n                    snappedCenter -\n                    physicalCenter\n                ) /\n                devicePixelRatio;\n\n            const translateX =\n                -handRect.width / 2 +\n                centerAdjustment;\n\n            return (\n                `translate(${translateX}px, -100%) ` +\n                `rotate(${angle}deg)`\n            );\n        }\n\n'''
if marker not in text:
    raise SystemExit('synchronizeHands marker not found')
text = text.replace(marker, helper + marker, 1)

path.write_text(text)

# Static behavioral assertions for the new format grammar.
import re
pattern = re.compile(r'^(?:hh:mm(?::ss)?|(?:h|0h):mm(?::ss)?(?: ?(?:a/p|A/P|AM/PM|A\\.M\\./P\\.M\\.|am/pm|a\\.m\\./p\\.m\\.))?)$')
valid = ['h:mm', 'h:mm:ss', '0h:mm', '0h:mm:ss', 'hh:mm', 'hh:mm:ss', 'h:mm AM/PM', '0h:mm:ss p.m./a.m.'.replace('p.m./a.m.','a.m./p.m.')]
for item in valid:
    if not pattern.fullmatch(item):
        raise SystemExit(f'expected valid format rejected: {item}')
for item in ['hh:mm AM/PM', 'hh:mm:ss PM', '00h:mm', 'hhh:mm']:
    if pattern.fullmatch(item):
        raise SystemExit(f'expected invalid format accepted: {item}')
